package com.example.ai_browser.model

import java.util.Locale

class LocalAI {

    fun analyze(text: String): AIResult {
        if (text.isBlank()) return AIResult("No content.", emptyList(), "Neutral", emptyList())

        val sentences = text.split(Regex("[.!?]")).filter { it.isNotBlank() }
        val words = text.split(Regex("\\W+")).filter { it.isNotBlank() }

        return AIResult(
            summary = generateSummary(sentences),
            keywords = extractKeywords(words),
            sentiment = analyzeSentiment(words),
            entities = extractEntities(text)
        )
    }

    private fun generateSummary(sentences: List<String>): String {
        return sentences.take(3).joinToString(". ") { it.trim() }
    }

    private fun extractKeywords(words: List<String>): List<String> {
        val stopWords = setOf("the", "is", "at", "which", "on", "and", "or", "in", "a", "an", "to", "for", "of", "with", "as", "by", "from", "that", "this", "it", "be", "are", "was", "were", "but", "not", "so", "if", "when", "then", "can", "will", "would", "should", "could", "about", "into", "over", "under", "after", "before", "between", "while", "during", "since", "until", "has", "have", "had", "do", "does", "did", "he", "she", "they", "we", "you", "i", "my", "your", "his", "her", "their", "our", "its", "who", "whom", "whose", "what", "where", "why", "how")
        val lowerCaseWords = words.map { it.lowercase(Locale.ROOT) }.filter { it.length > 3 && it !in stopWords }
        return lowerCaseWords.groupingBy { it }.eachCount().entries.sortedByDescending { it.value }.take(5).map { it.key }
    }

