    private fun extractEntities(text: String): List<String> {
        // Simple heuristic: Look for capitalized words that are not at the start of a sentence.
        // This is a naive implementation.
        val entities = mutableListOf<String>()
        val words = text.split(" ")
        for (i in 1 until words.size) {
            val word = words[i].trim(',', '.', '!', '?', '"', '\'')
            if (word.isNotEmpty() && word[0].isUpperCase() && !words[i-1].endsWith('.')) {
                entities.add(word)
            }
        }
        return entities.distinct().take(5)
    }
